#!/usr/bin/env node
/**
 * ULS Config Updater
 * 
 * Updates vite.config.build.mjs and uls.config.cjs with correct paths
 * Automatically detects UI package and configures ULS paths (generic - works for any UI repo name)
 * 
 * Usage:
 *   npx uls config
 *   npx uls update-config
 *   npm run uls-update-config
 */

import { resolve } from 'path'
import path from 'path'
import { readFileSync, writeFileSync, existsSync, readdirSync, lstatSync, mkdirSync, copyFileSync, realpathSync, unlinkSync } from 'fs'
import { createRequire } from 'module'

const projectRoot = process.cwd()

/**
 * Find UI package and ULS paths (generic - works for any UI repo name)
 * 
 * Detection logic:
 * 1. UI Repository: Has ULS directly in node_modules/uls-v2 → use directly
 * 2. Application Repository: Has a linked/installed UI package with ULS → use from UI package
 */
function findUiPackage() {
  // First, check if ULS is directly available (UI repository scenario)
  const ulsDirect = resolve(projectRoot, 'node_modules/uls-v2')
  if (existsSync(ulsDirect)) {
    return {
      uiPackagePath: null,
      ulsPath: ulsDirect,
      useUiPackage: false
    }
  }
  
  // Otherwise, we're in an application repository - look for any UI package
  // that contains ULS in its node_modules
  const nodeModulesPath = resolve(projectRoot, 'node_modules')
  
  if (existsSync(nodeModulesPath)) {
    try {
      // Scan node_modules for packages that have ULS
      const entries = readdirSync(nodeModulesPath, { withFileTypes: true })
      
      for (const entry of entries) {
        // Skip scoped packages directory (we'll check scoped packages separately)
        // Handle both directories and symlinks (symlinks show as files but are actually directories)
        if (!entry.name.startsWith('@')) {
          const candidatePath = resolve(nodeModulesPath, entry.name)
          
          // Check if it's a directory or symlink by trying to access it
          let isAccessible = false
          try {
            const stats = lstatSync(candidatePath)
            isAccessible = stats.isDirectory() || stats.isSymbolicLink()
          } catch (err) {
            // Not accessible, skip
            continue
          }
          
          if (isAccessible) {
            const ulsPath = resolve(candidatePath, 'node_modules/uls-v2')
            
            // Check if this package has ULS
            if (existsSync(ulsPath)) {
              return {
                uiPackagePath: candidatePath,
                ulsPath: ulsPath,
                useUiPackage: true
              }
            }
          }
        }
      }
      
      // Also check scoped packages (@scope/package-name)
      const scopedDirs = entries.filter(e => e.isDirectory() && e.name.startsWith('@'))
      for (const scopedDir of scopedDirs) {
        const scopedPath = resolve(nodeModulesPath, scopedDir.name)
        try {
          const scopedEntries = readdirSync(scopedPath, { withFileTypes: true })
          for (const scopedEntry of scopedEntries) {
            if (scopedEntry.isDirectory()) {
              const candidatePath = resolve(scopedPath, scopedEntry.name)
              const ulsPath = resolve(candidatePath, 'node_modules/uls-v2')
              
              if (existsSync(ulsPath)) {
                return {
                  uiPackagePath: candidatePath,
                  ulsPath: ulsPath,
                  useUiPackage: true
                }
              }
            }
          }
        } catch (err) {
          // Continue if can't read scoped directory
        }
      }
    } catch (err) {
      // Continue if can't read node_modules
    }
  }
  
  // Fallback: check relative paths (for development scenarios)
  const parentDir = resolve(projectRoot, '..')
  if (existsSync(parentDir)) {
    try {
      const siblings = readdirSync(parentDir, { withFileTypes: true })
      for (const sibling of siblings) {
        if (sibling.isDirectory() && sibling.name !== path.basename(projectRoot)) {
          const candidatePath = resolve(parentDir, sibling.name)
          const ulsPath = resolve(candidatePath, 'node_modules/uls-v2')
          
          if (existsSync(ulsPath)) {
            return {
              uiPackagePath: candidatePath,
              ulsPath: ulsPath,
              useUiPackage: true
            }
          }
        }
      }
    } catch (err) {
      // Continue if can't read parent directory
    }
  }
  
  return null
}

/**
 * Find ULS package directly (fallback if bs-ui not found)
 */
function findULSDirect() {
  const candidates = [
    resolve(projectRoot, 'node_modules/uls-v2'),
    resolve(projectRoot, 'node_modules/@uls/v2'),
  ]
  
  for (const candidate of candidates) {
    if (existsSync(resolve(candidate, 'src/styles/uls-master.less'))) {
      return candidate
    }
  }
  
  return null
}

/**
 * Load existing uls.config.cjs
 */
function loadUlsConfig() {
  const configPath = resolve(projectRoot, 'uls.config.cjs')
  if (existsSync(configPath)) {
    try {
      const require = createRequire(import.meta.url)
      return require(configPath)
    } catch (err) {
      console.warn('⚠️  Could not load uls.config.cjs:', err.message)
      return null
    }
  }
  return null
}

/**
 * Create vite.config.build.mjs template (if it doesn't exist)
 */
function createViteConfigTemplate(uiPackageInfo, ulsPath) {
  const viteConfigPath = resolve(projectRoot, 'vite.config.build.mjs')
  
  // Default paths
  const stylesPath = 'src/styles/uls'
  const passthroughPath = 'src/scripts/passthrough.js'
  
  // Generate path detection code
  let ulsPathCode
  if (uiPackageInfo && uiPackageInfo.useUiPackage) {
    const uiPackageRelativePath = path.relative(projectRoot, uiPackageInfo.uiPackagePath)
    const uiPackageNormalized = uiPackageRelativePath.replace(/\\/g, '/')
    ulsPathCode = `// Find UI package and ULS paths (auto-detected)
const uiPackagePath = resolve(__dirname, '${uiPackageNormalized}')
const ulsPackagePath = resolve(uiPackagePath, 'node_modules/uls-v2')`
  } else {
    ulsPathCode = `// Find ULS paths (UI repository - ULS installed directly)
const ulsPackagePath = resolve(__dirname, 'node_modules/uls-v2')`
  }
  
  const template = `import { defineConfig } from 'vite'
import { resolve, dirname } from 'path'
import { readFileSync, writeFileSync, mkdirSync, existsSync, watch } from 'fs'
import { createRequire } from 'module'
import less from 'less'

// Load ULS config to get correct paths (using createRequire for ES modules)
let ulsConfig = {}
try {
  const configPath = resolve(__dirname, 'uls.config.cjs')
  if (existsSync(configPath)) {
    const require = createRequire(import.meta.url)
    ulsConfig = require(configPath)
  }
} catch (err) {
  console.warn('Could not load uls.config.cjs, using defaults')
}

// Resolve paths from config or use defaults
const stylesPath = ulsConfig.stylesPath || '${stylesPath}'
const passthroughPath = ulsConfig.passthroughPath || '${passthroughPath}'

${ulsPathCode}

// Custom LESS build plugin (regular + minified)
// Supports Tailwind-like auto-rebuild when content files change
function lessBuildPlugin(options = {}) {
  const { entry, outDir, outFile, outMinFile } = options
  
  // Extract CSS compilation logic for reuse in watch mode
  const compileCSS = async (pluginContext) => {
    if (!existsSync(entry)) {
      pluginContext.error(\`Entry file not found: \${entry}\`)
      return
    }
    
    if (!existsSync(outDir)) {
      mkdirSync(outDir, { recursive: true })
    }
    
    const src = readFileSync(entry, 'utf8')
    const entryDir = resolve(entry, '..')
    const nodeModulesPath = resolve(__dirname, 'node_modules')
    const userStylesPath = resolve(process.cwd(), stylesPath)
    const userOverridesPath = resolve(userStylesPath, 'overrides')
    const ulsStylesPath = resolve(ulsPackagePath, 'styles')
    const ulsOverridesPath = resolve(ulsStylesPath, 'uls-overrides/less/uls-primereact')
    
    const cssResult = await less.render(src, {
      filename: entry,
      paths: [
        entryDir, 
        userStylesPath,
        userOverridesPath, // User's overrides directory for relative imports
        ulsStylesPath, // ULS base styles
        ulsOverridesPath, // ULS's own overrides directory for relative imports
        nodeModulesPath,
        resolve(process.cwd(), 'node_modules'),
        ${uiPackageInfo && uiPackageInfo.useUiPackage ? "resolve(uiPackagePath, 'node_modules')," : ''}
      ],
    })
    
    if (!cssResult || !cssResult.css) {
      pluginContext.error('LESS compilation failed: No CSS output')
      return
    }
    
    let css = cssResult.css
    
    writeFileSync(outFile, css, 'utf8')
    console.log(\`✅ LESS compiled → \${outFile}\`)

    // Minified CSS
    const minResult = await less.render(src, {
      filename: entry,
      paths: [
        entryDir, 
        userStylesPath,
        userOverridesPath, // User's overrides directory for relative imports
        ulsStylesPath, // ULS base styles
        ulsOverridesPath, // ULS's own overrides directory for relative imports
        nodeModulesPath,
        resolve(process.cwd(), 'node_modules'),
        ${uiPackageInfo && uiPackageInfo.useUiPackage ? "resolve(uiPackagePath, 'node_modules')," : ''}
      ],
      compress: true,
    })
    
    if (!minResult || !minResult.css) {
      pluginContext.error('LESS minification failed: No CSS output')
      return
    }
    
    let minCss = minResult.css
    
    writeFileSync(outMinFile, minCss, 'utf8')
    console.log(\`✅ LESS minified → \${outMinFile}\`)
  }
  
  return {
    name: 'less-build',
    async buildStart() {
      try {
        if (!entry) {
          this.error('Entry file is required')
          return
        }
        
        // Add entry file to watch list
        if (entry && existsSync(entry)) {
          this.addWatchFile(entry)
        }
        
        // Watch LESS files in ULS package and override directories
        try {
          const { glob } = await import('glob')
          
          // Watch ULS core LESS files
          const ulsStylesPath = resolve(ulsPackagePath, 'src/styles')
          if (existsSync(ulsStylesPath)) {
            try {
              const ulsLessFiles = glob.sync(\`\${ulsStylesPath}/**/*.less\`, {
                ignore: ['node_modules/**', 'dist/**'],
                absolute: true
              })
              ulsLessFiles.forEach(file => {
                if (existsSync(file)) {
                  this.addWatchFile(file)
                }
              })
              console.log(\`👀 Watching \${ulsLessFiles.length} ULS LESS files\`)
            } catch (err) {
              // Continue if glob fails
            }
          }
          
          // Watch user override LESS files (from stylesPath config)
          const userStylesPath = resolve(process.cwd(), stylesPath)
          if (existsSync(userStylesPath)) {
            try {
              const userLessFiles = glob.sync(\`\${userStylesPath}/**/*.less\`, {
                ignore: ['node_modules/**', 'dist/**'],
                absolute: true
              })
              userLessFiles.forEach(file => {
                if (existsSync(file)) {
                  this.addWatchFile(file)
                }
              })
              if (userLessFiles.length > 0) {
                console.log(\`👀 Watching \${userLessFiles.length} user override LESS files\`)
              }
            } catch (err) {
              // Continue if glob fails
            }
          }
          
          // Watch override files in uls-overrides directory (common pattern)
          const overridesPath = resolve(process.cwd(), 'uls-overrides')
          if (existsSync(overridesPath)) {
            try {
              const overrideLessFiles = glob.sync(\`\${overridesPath}/**/*.less\`, {
                ignore: ['node_modules/**', 'dist/**'],
                absolute: true
              })
              overrideLessFiles.forEach(file => {
                if (existsSync(file)) {
                  this.addWatchFile(file)
                }
              })
              if (overrideLessFiles.length > 0) {
                console.log(\`👀 Watching \${overrideLessFiles.length} override LESS files\`)
              }
            } catch (err) {
              // Continue if glob fails
            }
          }
          
          // Watch override files in ULS package's override directory
          const ulsOverridesPath = resolve(ulsPackagePath, 'src/styles/uls-overrides')
          if (existsSync(ulsOverridesPath)) {
            try {
              const ulsOverrideLessFiles = glob.sync(\`\${ulsOverridesPath}/**/*.less\`, {
                ignore: ['node_modules/**', 'dist/**'],
                absolute: true
              })
              ulsOverrideLessFiles.forEach(file => {
                if (existsSync(file)) {
                  this.addWatchFile(file)
                }
              })
              if (ulsOverrideLessFiles.length > 0) {
                console.log(\`👀 Watching \${ulsOverrideLessFiles.length} ULS override LESS files\`)
              }
            } catch (err) {
              // Continue if glob fails
            }
          }
        } catch (err) {
          // glob might not be available, continue without watching LESS files
        }
        
        await compileCSS(this)
      } catch (error) {
        const errorMessage = error?.message || error?.toString() || 'Unknown error'
        const errorStack = error?.stack || ''
        this.error(\`LESS compilation failed: \${errorMessage}\${errorStack ? '\\n' + errorStack : ''}\`)
        throw error
      }
    },
    // Auto-rebuild when LESS files change (Rollup watch mode)
    watchChange(id) {
      const isLessFile = id.endsWith('.less')
      
      if (isLessFile) {
        console.log(\`📝 LESS file changed: \${id}\`)
        console.log(\`🔄 Rebuilding CSS...\`)
        
        // Use setTimeout to debounce and avoid multiple rebuilds
        if (this._rebuildTimeout) {
          clearTimeout(this._rebuildTimeout)
        }
        
        this._rebuildTimeout = setTimeout(async () => {
          try {
            await compileCSS(this)
            console.log(\`✨ CSS updated automatically!\`)
          } catch (err) {
            console.error(\`❌ Failed to rebuild CSS:\`, err.message)
          }
        }, 100) // 100ms debounce
      }
    },
    closeWatcher() {
      // Clean up timeout when watcher closes
      if (this._rebuildTimeout) {
        clearTimeout(this._rebuildTimeout)
      }
      if (globalRebuildTimeout) {
        clearTimeout(globalRebuildTimeout)
      }
      
      // Close all file watchers
      globalLessFileWatchers.forEach(({ watcher }) => {
        try {
          watcher.close()
        } catch (err) {
          // Ignore errors when closing watchers
        }
      })
      globalLessFileWatchers = []
    },
  }
}

export default defineConfig(({ mode }) => {
  const config = {
    plugins: [],
    build: {
      emptyOutDir: false, // Keep both CSS and JS outputs
    },
  }

  // Resolve entry files - use user's local uls-master.less if it exists, otherwise fallback to ULS package
  const userLessMaster = resolve(process.cwd(), stylesPath, 'uls-master.less')
  const lessEntry = mode === 'less-only'
    ? (existsSync(userLessMaster) ? userLessMaster : resolve(ulsPackagePath, 'src/styles/uls.less'))
    : (existsSync(userLessMaster) ? userLessMaster : resolve(ulsPackagePath, 'src/styles/uls-master.less'))
  const passthroughEntry = resolve(__dirname, passthroughPath)

  // LESS-only modes
  if (mode === 'less' || mode === 'less-only') {
    // Validate entry file exists
    if (!existsSync(lessEntry)) {
      console.error(\`❌ Error: LESS entry file not found: \${lessEntry}\`)
      console.error(\`   Expected path: \${lessEntry}\`)
      console.error(\`   Styles path from config: \${stylesPath}\`)
      console.error(\`   Current directory: \${__dirname}\`)
      throw new Error(\`LESS entry file not found: \${lessEntry}\`)
    }
    
    config.plugins.push(
      lessBuildPlugin({
        entry: lessEntry,
        outDir: resolve(__dirname, 'dist/css'),
        outFile: resolve(__dirname, 'dist/css/uls.css'),
        outMinFile: resolve(__dirname, 'dist/css/uls.min.css'),
      })
    )
    // Disable JS build in LESS-only mode
    config.build.lib = false
    // Provide a dummy input to satisfy Rollup (plugins handle actual compilation)
    // Create a minimal dummy file if passthrough doesn't exist (only during build, not during init)
    const dummyInput = resolve(__dirname, passthroughPath)
    // Note: Don't create dummy file during init - only create during actual build
    // The build process will handle creating necessary files
    config.build.rollupOptions = {
      input: dummyInput,
      external: ['primereact/utils'],
      output: {
        format: 'es',
        // Suppress JS output - we only want CSS from the plugin
        entryFileNames: () => '.vite-temp/empty.js',
      }
    }
    return config
  }

  // JS-only mode
  if (mode === 'js') {
    config.build = {
      lib: {
        entry: passthroughEntry,
        name: 'ULSPassthrough',
        fileName: () => \`passthrough.js\`,
        formats: ['es'],
      },
      outDir: resolve(__dirname, 'dist/js'),
      minify: true,
      emptyOutDir: false,
      rollupOptions: {
        external: ['primereact/utils'],
        output: {
          format: 'es',
          entryFileNames: 'passthrough.js',
        },
      },
    }
    return config
  }

  // Default: build both LESS and JS (JS is optional)
  // Validate entry file exists
  if (!existsSync(lessEntry)) {
    console.error(\`❌ Error: LESS entry file not found: \${lessEntry}\`)
    console.error(\`   Expected path: \${lessEntry}\`)
    console.error(\`   Styles path from config: \${stylesPath}\`)
    console.error(\`   Current directory: \${__dirname}\`)
    throw new Error(\`LESS entry file not found: \${lessEntry}\`)
  }
  
  // Add LESS build plugin
  config.plugins.push(
    lessBuildPlugin({
      entry: lessEntry,
      outDir: resolve(__dirname, 'dist/css'),
      outFile: resolve(__dirname, 'dist/css/uls.css'),
      outMinFile: resolve(__dirname, 'dist/css/uls.min.css'),
    })
  )

  // Build JS only if passthrough file exists
  if (existsSync(passthroughEntry)) {
    config.build.lib = {
      entry: passthroughEntry,
      name: 'ULSPassthrough',
      fileName: () => \`passthrough.js\`,
      formats: ['es'],
    }
    config.build.outDir = resolve(__dirname, 'dist/js')
    config.build.minify = true
    config.build.rollupOptions = {
      external: ['primereact/utils'],
      output: {
        format: 'es',
        entryFileNames: 'passthrough.js',
      },
    }
  } else {
    // Passthrough doesn't exist - skip JS build, create dummy input for Rollup
    console.warn(\`⚠️  Passthrough file not found: \${passthroughEntry}\`)
    console.warn(\`   Skipping JS build. Only CSS will be generated.\`)
    console.warn(\`   Tip: Run 'npm run uls-passthrough' to create the passthrough file\`)
    
    // Create a minimal dummy file for Rollup (only during build, not during init)
    const dummyInput = resolve(__dirname, passthroughPath)
    // Note: Don't create dummy file during init - only create during actual build
    // The build process will handle creating necessary files
    
    config.build.lib = false
    config.build.rollupOptions = {
      input: dummyInput,
      external: ['primereact/utils'],
      output: {
        format: 'es',
        // Suppress JS output - we only want CSS from the plugin
        entryFileNames: () => '.vite-temp/empty.js',
      },
    }
  }

  return config
})
`
  
  writeFileSync(viteConfigPath, template, 'utf8')
  console.log('✅ Created vite.config.build.mjs')
  return true
}

/**
 * Update vite.config.build.mjs with correct paths
 */
function updateViteConfig(uiPackageInfo, ulsPath) {
  const viteConfigPath = resolve(projectRoot, 'vite.config.build.mjs')
  
  if (!existsSync(viteConfigPath)) {
    // Create it if it doesn't exist
    return createViteConfigTemplate(uiPackageInfo, ulsPath)
  }
  
  let content = readFileSync(viteConfigPath, 'utf8')
  let updated = false
  
  // Determine ULS source path
  const ulsSourcePath = uiPackageInfo ? uiPackageInfo.ulsPath : ulsPath
  
  if (!ulsSourcePath) {
    console.error('❌ ULS package not found. Install UI package with ULS or uls-v2 directly')
    return false
  }
  
  // Update import to include dirname
  if (!content.includes("import { resolve, dirname } from 'path'")) {
    content = content.replace(
      /import { resolve } from 'path'/g,
      "import { resolve, dirname } from 'path'"
    )
    updated = true
  }
  
  // Add UI package and ULS path detection at top level (after config loading)
  let pathDetectionCode
  if (uiPackageInfo && uiPackageInfo.useUiPackage) {
    // Application repo: UI package found, use ULS from UI package
    // Resolve symlinks to get the actual path (handles npm link)
    let actualUiPackagePath = uiPackageInfo.uiPackagePath
    try {
      if (existsSync(actualUiPackagePath)) {
        actualUiPackagePath = realpathSync(actualUiPackagePath)
      }
    } catch (err) {
      // If realpathSync fails, use original path
    }
    
    // Use absolute path resolution that handles symlinks
    // realpathSync is already imported at the top via fs import
    pathDetectionCode = `
// Find UI package and ULS paths (auto-detected for application repository)
// Resolve symlinks to handle npm link correctly
let uiPackagePath = resolve(__dirname, '${path.relative(projectRoot, uiPackageInfo.uiPackagePath).replace(/\\/g, '/')}')
try {
  if (existsSync(uiPackagePath)) {
    uiPackagePath = realpathSync(uiPackagePath)
  }
} catch (err) {
  // Continue with original path if realpathSync fails
}
const ulsPackagePath = resolve(uiPackagePath, 'node_modules/uls-v2')
`
  } else {
    // UI repo: ULS directly available
    pathDetectionCode = `
// Find ULS paths (UI repository - ULS installed directly)
const ulsPackagePath = resolve(__dirname, 'node_modules/uls-v2')
`
  }
  
  // Check if paths are already defined
  if (!content.includes('const ulsPackagePath =')) {
    // Insert after config loading section
    const configLoadingEnd = content.indexOf('const passthroughPath =')
    if (configLoadingEnd > 0) {
      const insertPos = content.lastIndexOf('\n', configLoadingEnd) + 1
      content = content.slice(0, insertPos) + pathDetectionCode + content.slice(insertPos)
      updated = true
    }
  } else {
    // Update existing path detection (handle both old bsUiPath and new uiPackagePath)
    const pathDetectionRegex = /const (bsUiPath|uiPackagePath) =[^\n]*\nconst ulsPackagePath =[^\n]*/s
    if (pathDetectionRegex.test(content)) {
      content = content.replace(pathDetectionRegex, pathDetectionCode.trim())
      updated = true
    }
  }
  
  // Update LESS entry to use user's local file first, then fallback to ULS package
  const lessEntryPattern = /const lessEntry = mode === 'less-only'[\s\S]*?resolve\([^)]+\)[\s\S]*?resolve\([^)]+\)/
  const newLessEntry = `// Resolve entry files - use user's local uls-master.less if it exists, otherwise fallback to ULS package
  const userLessMaster = resolve(process.cwd(), stylesPath, 'uls-master.less')
  const lessEntry = mode === 'less-only'
    ? (existsSync(userLessMaster) ? userLessMaster : resolve(ulsPackagePath, 'src/styles/uls.less'))
    : (existsSync(userLessMaster) ? userLessMaster : resolve(ulsPackagePath, 'src/styles/uls-master.less'))`
  
  if (lessEntryPattern.test(content)) {
    content = content.replace(lessEntryPattern, newLessEntry)
    updated = true
  }
  
  // Update LESS paths in compileCSS function to include ULS paths
  const lessPathsPattern = /paths: \[([^\]]+)\]/s
  const lessPathsMatch = content.match(/const cssResult = await less\.render\(src, \{[\s\S]*?paths: \[([^\]]+)\]/)
  if (lessPathsMatch) {
    const existingPaths = lessPathsMatch[1]
    if (!existingPaths.includes('ulsPackagePath')) {
      const uiPackagePathLine = uiPackageInfo && uiPackageInfo.useUiPackage ? "resolve(uiPackagePath, 'node_modules')," : ''
      const newPaths = existingPaths.trim() + ',\n        // Add paths to resolve ULS imports\n        resolve(ulsPackagePath, \'styles\')' + (uiPackagePathLine ? ',\n        ' + uiPackagePathLine : '')
      content = content.replace(lessPathsMatch[0], lessPathsMatch[0].replace(existingPaths, newPaths))
      updated = true
    }
  }
  
  // Update PurgeCSS config import to use ulsPackagePath
  // Fix old pattern: node_modules/uls-v2/scripts/purgecss-config.mjs
  const purgeConfigPattern = /const ulsPackagePath = resolve\(__dirname, 'node_modules\/uls-v2\/scripts\/purgecss-config\.mjs'\)/
  if (purgeConfigPattern.test(content)) {
    content = content.replace(
      purgeConfigPattern,
      "const purgeConfigPath = resolve(ulsPackagePath, 'src/scripts/build/purgecss-config.mjs')"
    )
    updated = true
  }
  
  // Fix wrong path: src/scripts/purgecss-config.mjs (missing build/)
  const wrongPurgePathPattern = /resolve\(ulsPackagePath, ['"]src\/scripts\/purgecss-config\.mjs['"]\)/g
  if (wrongPurgePathPattern.test(content)) {
    content = content.replace(
      wrongPurgePathPattern,
      "resolve(ulsPackagePath, 'src/scripts/build/purgecss-config.mjs')"
    )
    updated = true
  }
  
  // Fix PurgeCSS import to use purgeConfigPath instead of ulsPackagePath
  const purgeImportPattern = /if \(existsSync\(ulsPackagePath\)\) \{[\s\S]*?const purgeConfigModule = await import\(ulsPackagePath\)/
  if (purgeImportPattern.test(content)) {
    content = content.replace(
      /if \(existsSync\(ulsPackagePath\)\) \{[\s\S]*?const purgeConfigModule = await import\(ulsPackagePath\)/,
      `if (existsSync(purgeConfigPath)) {
              const purgeConfigModule = await import(purgeConfigPath)`
    )
    updated = true
  }
  
  // Fix path.dirname to use dirname
  if (content.includes('path.dirname')) {
    content = content.replace(/path\.dirname/g, 'dirname')
    updated = true
  }
  
  // Update minified CSS purge section to use ulsPackagePath
  const minPurgePattern = /const ulsPackagePath = resolve\(__dirname, 'node_modules\/uls-v2\/scripts\/purgecss-config\.mjs'\)/
  if (minPurgePattern.test(content)) {
    content = content.replace(
      minPurgePattern,
      "const purgeConfigPath = resolve(ulsPackagePath, 'src/scripts/build/purgecss-config.mjs')"
    )
    updated = true
  }
  
  if (updated) {
    writeFileSync(viteConfigPath, content, 'utf8')
    console.log('✅ Updated vite.config.build.mjs with correct paths')
    return true
  } else {
    console.log('ℹ️  vite.config.build.mjs already has correct paths')
    return false
  }
}

/**
 * Ensure package.json has required ULS scripts
 * This function updates package.json scripts before updating config files
 */
function ensurePackageJsonScripts(uiPackageInfo) {
  const packageJsonPath = resolve(projectRoot, 'package.json')
  
  if (!existsSync(packageJsonPath)) {
    console.log('ℹ️  package.json not found - skipping script updates')
    return false
  }
  
  let packageJson
  try {
    const content = readFileSync(packageJsonPath, 'utf8')
    packageJson = JSON.parse(content)
  } catch (err) {
    console.warn(`⚠️  Could not parse package.json: ${err.message}`)
    return false
  }
  
  // Ensure scripts object exists
  if (!packageJson.scripts) {
    packageJson.scripts = {}
  }
  
  // Ensure devDependencies object exists
  if (!packageJson.devDependencies) {
    packageJson.devDependencies = {}
  }
  
  // Load config to get srcPath (load once, use multiple times)
  const ulsConfig = loadUlsConfig()
  const srcPath = ulsConfig?.srcPath || 'src'
  
  // Copy find-uls.mjs helper script if it doesn't exist (needed for clean script execution)
  // Try multiple possible locations for ULS package
  const possibleUlsPaths = [
    resolve(projectRoot, 'node_modules', 'uls-v2', 'src', 'scripts', 'find-uls.mjs'),
    ...(uiPackageInfo && uiPackageInfo.ulsPath 
      ? [resolve(uiPackageInfo.ulsPath, 'src', 'scripts', 'find-uls.mjs')]
      : [])
  ]
  
  // Place find-uls.mjs in src/scripts/ folder for user projects
  const findUlsScriptPath = resolve(projectRoot, srcPath, 'scripts', 'find-uls.mjs')
  let ulsFindUlsScriptPath = null
  
  for (const possiblePath of possibleUlsPaths) {
    if (existsSync(possiblePath)) {
      ulsFindUlsScriptPath = possiblePath
      break
    }
  }
  
  if (!existsSync(findUlsScriptPath) && ulsFindUlsScriptPath) {
    try {
      // Place find-uls.mjs in src/scripts/ folder for user projects
      const scriptsDir = path.dirname(findUlsScriptPath)
      if (!existsSync(scriptsDir)) {
        mkdirSync(scriptsDir, { recursive: true })
      }
      copyFileSync(ulsFindUlsScriptPath, findUlsScriptPath)
      console.log(`📝 Created helper script: ${path.relative(projectRoot, findUlsScriptPath)}`)
    } catch (err) {
      // Continue if can't copy (might not be critical)
      console.warn(`⚠️  Could not copy find-uls.mjs: ${err.message}`)
    }
  }
  
  let wasUpdated = false
  
  // Determine if this is a UI repo or app repo
  const hasUlsDirect = existsSync(resolve(projectRoot, 'node_modules/uls-v2'))
  const isUIRepo = hasUlsDirect && (!uiPackageInfo || !uiPackageInfo.useUiPackage)
  
  // Helper function to create ULS script command using find-uls.mjs
  function createUlsScriptCommand(scriptName, command = '') {
    // Place find-uls.mjs in src/scripts/ folder for user projects
    const findUlsScript = `node ${path.posix.join(srcPath, 'scripts', 'find-uls.mjs')}`
    return command 
      ? `${findUlsScript} ${scriptName} ${command}`
      : `${findUlsScript} ${scriptName}`
  }
  
  // Get package name for bin command prefix (for UI repos)
  const packageName = packageJson.name || path.basename(projectRoot)
  const binPrefix = packageName.replace(/[@\/]/g, '-')
  
  // Build scripts that should be available in both UI and app repos
  const buildScripts = {
    'build': 'vite build -c vite.config.build.mjs --no-purge',
    'build:purge': 'vite build -c vite.config.build.mjs',
    'build:less': 'vite build -c vite.config.build.mjs -m less',
    'build:less:master': 'vite build -c vite.config.build.mjs -m less-only',
    'build:less:no-purge': 'vite build -c vite.config.build.mjs -m less --no-purge',
    'build:less:with-js': 'vite build -c vite.config.build.mjs -m less --scan-js',
    'build:js': 'vite build -c vite.config.build.mjs -m js',
    'watch': 'vite build -c vite.config.build.mjs -w',
    'watch:less': 'vite build -c vite.config.build.mjs -m less -w',
  }
  
  // Add build scripts (always add these)
  Object.entries(buildScripts).forEach(([key, value]) => {
    if (!packageJson.scripts[key] || packageJson.scripts[key] !== value) {
      packageJson.scripts[key] = value
      wasUpdated = true
    }
  })
  
  // Add dev and demo-app scripts (for development workflow)
  // Check if demo app exists - if it does, use that path, otherwise use vite directly
  const demoAppPath = resolve(projectRoot, 'src/demo/uls-primereact')
  const libsDemoPath = resolve(projectRoot, 'src/libs/uls-primereact')
  const demoAppExists = existsSync(demoAppPath) || existsSync(libsDemoPath)
  
  // Set up demo-app script
  let demoAppScript = 'vite' // Default: run vite directly
  if (demoAppExists) {
    // Use libs path if it exists, otherwise use demo path
    const demoPath = existsSync(libsDemoPath) 
      ? 'src/libs/uls-primereact' 
      : 'src/demo/uls-primereact'
    demoAppScript = `npm --prefix ${demoPath} run dev`
  }
  
  // Always add/update demo-app script (safe to update)
  if (!packageJson.scripts['demo-app'] || packageJson.scripts['demo-app'] !== demoAppScript) {
    packageJson.scripts['demo-app'] = demoAppScript
    wasUpdated = true
  }
  
  // Handle dev script - be conservative, only update if safe
  const currentDev = packageJson.scripts['dev'] || ''
  const devScript = 'npm run watch & npm run demo-app'
  
  // Only update dev script if:
  // 1. It doesn't exist, OR
  // 2. It's exactly "vite" (no custom flags/args), OR
  // 3. It already includes "watch" (user might have set it up already)
  const shouldUpdateDev = 
    !currentDev || 
    currentDev.trim() === 'vite' || 
    currentDev.includes('watch')
  
  if (shouldUpdateDev && currentDev !== devScript) {
    packageJson.scripts['dev'] = devScript
    wasUpdated = true
  } else if (currentDev && currentDev !== 'vite' && !currentDev.includes('watch')) {
    // User has custom dev script - create uls-dev as alternative
    if (!packageJson.scripts['uls-dev']) {
      packageJson.scripts['uls-dev'] = devScript
      wasUpdated = true
      console.log('ℹ️  Preserved your custom "dev" script. Use "npm run uls-dev" for ULS watch + demo-app')
    }
  }
  
  // Ensure required dev dependencies are present
  const requiredDevDeps = {
    'vite': '^7.3.0',
    'less': '^4.4.2',
    'postcss': '^8.5.6',
    '@fullhuman/postcss-purgecss': '^7.0.2',
    'glob': '^11.0.0',  // Required by purgecss-config.mjs for file scanning
  }
  
  Object.entries(requiredDevDeps).forEach(([dep, version]) => {
    if (!packageJson.devDependencies[dep]) {
      packageJson.devDependencies[dep] = version
      wasUpdated = true
    }
  })
  
  if (isUIRepo) {
    // UI Repository: Add bin entries AND scripts
    if (!packageJson.bin) {
      packageJson.bin = {}
      wasUpdated = true
    }
    
    const binEntries = {
      [`${binPrefix}-uls-config`]: 'node_modules/uls-v2/src/scripts/init/update-config.mjs',
      [`${binPrefix}-uls-init`]: 'node_modules/uls-v2/src/scripts/cli/uls.js',
    }
    
    Object.entries(binEntries).forEach(([key, value]) => {
      if (packageJson.bin[key] !== value) {
        packageJson.bin[key] = value
        wasUpdated = true
      }
    })
    
    // Add npm scripts
    const requiredScripts = {
      'uls-init': createUlsScriptCommand('uls.js', 'init'),
      'uls-config': createUlsScriptCommand('update-config.mjs'),
      'uls-update-config': createUlsScriptCommand('update-config.mjs'),
    }
    
    Object.entries(requiredScripts).forEach(([key, value]) => {
      if (packageJson.scripts[key] !== value) {
        packageJson.scripts[key] = value
        wasUpdated = true
      }
    })
  } else {
    // Application Repository: Use npm run --prefix to call scripts from linked UI package
    let uiPackageName = null
    
    if (uiPackageInfo && uiPackageInfo.useUiPackage) {
      try {
        const uiPackageJsonPath = resolve(uiPackageInfo.uiPackagePath, 'package.json')
        if (existsSync(uiPackageJsonPath)) {
          const uiPackageJson = JSON.parse(readFileSync(uiPackageJsonPath, 'utf8'))
          uiPackageName = uiPackageJson.name || path.basename(uiPackageInfo.uiPackagePath)
        }
      } catch (err) {
        uiPackageName = path.basename(uiPackageInfo.uiPackagePath)
      }
    }
    
    if (uiPackageName && uiPackageInfo.uiPackagePath) {
      const uiPackageAbsolutePath = uiPackageInfo.uiPackagePath
      const uiPackageRelativePath = path.relative(projectRoot, uiPackageInfo.uiPackagePath).replace(/\\/g, '/')
      
      const requiredScripts = {
        'uls-init': `npm run --prefix "${uiPackageAbsolutePath}" uls-init || node ${uiPackageRelativePath}/node_modules/uls-v2/src/scripts/uls.js init`,
        'uls-config': `npm run --prefix "${uiPackageAbsolutePath}" uls-config || node ${uiPackageRelativePath}/node_modules/uls-v2/src/scripts/update-config.mjs`,
        'uls-update-config': `npm run --prefix "${uiPackageAbsolutePath}" uls-config || node ${uiPackageRelativePath}/node_modules/uls-v2/src/scripts/update-config.mjs`,
      }
      
      Object.entries(requiredScripts).forEach(([key, value]) => {
        if (packageJson.scripts[key] !== value) {
          packageJson.scripts[key] = value
          wasUpdated = true
        }
      })
    } else {
      // Fallback: Use find-uls.mjs if UI package not found
      const requiredScripts = {
        'uls-init': createUlsScriptCommand('uls.js', 'init'),
        'uls-config': createUlsScriptCommand('update-config.mjs'),
        'uls-update-config': createUlsScriptCommand('update-config.mjs'),
      }
      
      Object.entries(requiredScripts).forEach(([key, value]) => {
        if (packageJson.scripts[key] !== value) {
          packageJson.scripts[key] = value
          wasUpdated = true
        }
      })
    }
  }
  
  // Write package.json back if updated
  if (wasUpdated) {
    const content = JSON.stringify(packageJson, null, 2) + '\n'
    writeFileSync(packageJsonPath, content, 'utf8')
    console.log('✅ Updated package.json with ULS scripts')
    return true
  }
  
  return false
}

/**
 * Update uls.config.cjs (preserve user settings, only update if missing)
 */
function updateUlsConfig() {
  const configPath = resolve(projectRoot, 'uls.config.cjs')
  const existingConfig = loadUlsConfig()
  
  // If config exists and has purge settings, don't overwrite
  if (existingConfig && existingConfig.purge) {
    console.log('ℹ️  uls.config.cjs already exists with purge settings - preserving')
    return false
  }
  
  // Create or update config
  const defaultConfig = {
    stylesPath: existingConfig?.stylesPath || 'src/styles/uls',
    passthroughPath: existingConfig?.passthroughPath || 'src/scripts/passthrough.js',
    purge: {
      htmlFiles: existingConfig?.purge?.htmlFiles || ['index.html'],
      sourceDirs: existingConfig?.purge?.sourceDirs || ['src'],
      safelist: existingConfig?.purge?.safelist || []
    }
  }
  
  const configContent = `/**
 * ULS Generator Config
 * Auto-updated via: npx uls update-config
 */
module.exports = ${JSON.stringify(defaultConfig, null, 2)};
`
  
  writeFileSync(configPath, configContent, 'utf8')
  console.log('✅ Updated uls.config.cjs')
  return true
}

/**
 * Update vite.config.js/mjs (main dev config) to include ULS dev plugin
 * This enables Tailwind-like auto-rebuild during npm run dev
 * Prefers .mjs extension to ensure ES module mode
 */
function updateViteDevConfig(uiPackageInfo, ulsPath) {
  const viteConfigPath = resolve(projectRoot, 'vite.config.js')
  const viteConfigMjsPath = resolve(projectRoot, 'vite.config.mjs')
  
  // Smart approach: Prefer updating existing vite.config.js in place
  // Only create .mjs if .js file would cause ES module errors
  // Users don't need to change extensions - we handle it automatically
  let configPath = null
  let migrationMessage = null
  
  // Check package.json for "type": "module"
  const packageJsonPath = resolve(projectRoot, 'package.json')
  let hasTypeModule = false
  if (existsSync(packageJsonPath)) {
    try {
      const pkg = JSON.parse(readFileSync(packageJsonPath, 'utf8'))
      hasTypeModule = pkg.type === 'module'
    } catch (err) {
      // Continue - assume no type module
    }
  }
  
  if (existsSync(viteConfigMjsPath)) {
    // .mjs already exists - use it (always safe)
    configPath = viteConfigMjsPath
    console.log('ℹ️  Using existing vite.config.mjs')
  } else if (existsSync(viteConfigPath)) {
    // .js exists - check if we can use it or need .mjs
    const jsContent = readFileSync(viteConfigPath, 'utf8')
    const usesESModules = jsContent.includes('import ') || jsContent.includes('export ')
    
    if (hasTypeModule) {
      // Project has "type": "module" - .js works fine as ES Module
      // Update existing .js file in place (no extension change needed)
      configPath = viteConfigPath
      console.log('ℹ️  Updating existing vite.config.js (project has "type": "module")')
    } else if (!usesESModules) {
      // File uses CommonJS syntax - .js works fine
      // Update existing .js file in place (no extension change needed)
      configPath = viteConfigPath
      console.log('ℹ️  Updating existing vite.config.js (CommonJS syntax)')
    } else {
      // No "type": "module" but file uses ES syntax - .js will cause errors
      // Solution: Create .mjs and tell user to delete .js (or add "type": "module")
      configPath = viteConfigMjsPath
      const backupPath = viteConfigPath + '.backup'
      if (!existsSync(backupPath)) {
        writeFileSync(backupPath, jsContent, 'utf8')
      }
      writeFileSync(configPath, jsContent, 'utf8')
      
      // Store migration message to show after plugin is added
      migrationMessage = `
⚠️  IMPORTANT: vite.config.js uses ES modules but your package.json lacks "type": "module"
   ✓ Created vite.config.mjs (Vite will use this automatically)
   ✓ Backed up vite.config.js → vite.config.js.backup
   
   📋 Next steps (choose one):
   
   Option 1 (Recommended): Delete vite.config.js
      → Vite will automatically use vite.config.mjs
      → Run: rm vite.config.js
   
   Option 2: Add "type": "module" to package.json
      → Then vite.config.js will work as ES Module
      → Add: "type": "module" to your package.json`
    }
  } else {
    // No config exists - create .mjs (always safe, works everywhere)
    configPath = viteConfigMjsPath
    const defaultConfig = `import { defineConfig } from 'vite'

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [],
})
`
    writeFileSync(configPath, defaultConfig, 'utf8')
    console.log('✅ Created vite.config.mjs (works in all project types)')
  }
  
  let content = readFileSync(configPath, 'utf8')
  let updated = false
  
  // Determine ULS source path
  const ulsSourcePath = uiPackageInfo ? uiPackageInfo.ulsPath : ulsPath
  
  if (!ulsSourcePath) {
    console.warn('⚠️  ULS package not found - skipping vite.config.js update')
    return false
  }
  
  // Find UI package path for path detection
  // Note: Don't include imports here - they're already added above
  let pathDetectionCode = ''
  if (uiPackageInfo && uiPackageInfo.useUiPackage) {
    let actualUiPackagePath = uiPackageInfo.uiPackagePath
    try {
      if (existsSync(actualUiPackagePath)) {
        actualUiPackagePath = realpathSync(actualUiPackagePath)
      }
    } catch (err) {
      // Continue with original path
    }
    
    pathDetectionCode = `
// Find UI package and ULS paths (for dev mode CSS watching)
let uiPackagePath = resolve(__dirname, '${path.relative(projectRoot, uiPackageInfo.uiPackagePath).replace(/\\/g, '/')}')
try {
  if (existsSync(uiPackagePath)) {
    uiPackagePath = realpathSync(uiPackagePath)
  }
} catch (err) {
  // Continue with original path
}
const ulsPackagePath = resolve(uiPackagePath, 'node_modules/uls-v2')
`
  } else {
    pathDetectionCode = `
// Find ULS paths (for dev mode CSS watching)
const ulsPackagePath = resolve(__dirname, 'node_modules/uls-v2')
`
  }
  
  // Clean up duplicate imports first (fix existing issues)
  // Remove duplicate realpathSync imports
  const duplicateRealpathSyncMatches = content.match(/import\s*{\s*realpathSync\s*}\s*from\s*['"]fs['"]/g)
  if (duplicateRealpathSyncMatches && duplicateRealpathSyncMatches.length > 1) {
    // Keep only the first one, remove the rest
    let firstFound = false
    content = content.replace(/import\s*{\s*realpathSync\s*}\s*from\s*['"]fs['"]/g, (match) => {
      if (!firstFound) {
        firstFound = true
        return match
      }
      return '' // Remove duplicate
    })
    // Clean up empty lines
    content = content.replace(/\n\s*\n\s*\n/g, '\n\n')
    updated = true
  }
  
  // Check if ULS dev plugin is already imported/added
  const hasUlsDevPlugin = content.includes('ulsDevPlugin') || content.includes('ULS Dev Plugin')
  
  if (!hasUlsDevPlugin) {
    // Add imports at the top
    if (!content.includes("import { resolve } from 'path'")) {
      const importMatch = content.match(/^import .+ from ['"]vite['"]/)
      if (importMatch) {
        content = content.replace(
          /^import .+ from ['"]vite['"]/m,
          `import { defineConfig } from 'vite'\nimport { resolve } from 'path'`
        )
        updated = true
      } else {
        // Add after existing imports
        const firstImport = content.match(/^import .+/m)
        if (firstImport) {
          content = content.replace(
            /^import .+/m,
            `import { defineConfig } from 'vite'\nimport { resolve } from 'path'\n$&`
          )
          updated = true
        }
      }
    }
    
    // Add fs imports if not present
    if (!content.includes("import { existsSync")) {
      content = content.replace(
        /import { resolve } from 'path'/,
        `import { resolve } from 'path'\nimport { existsSync, realpathSync, readFileSync, writeFileSync, mkdirSync } from 'fs'\nimport { createRequire } from 'module'`
      )
      updated = true
    } else if (!content.includes("readFileSync")) {
      // Add missing fs functions if existsSync is present but others aren't
      content = content.replace(
        /import { existsSync([^}]*)} from 'fs'/,
        `import { existsSync$1, readFileSync, writeFileSync, mkdirSync } from 'fs'`
      )
      if (!content.includes("createRequire")) {
        content = content.replace(
          /import { resolve } from 'path'/,
          `import { resolve } from 'path'\nimport { createRequire } from 'module'`
        )
      }
      updated = true
    }
    
    // Add path detection code before the export
    const exportMatch = content.match(/export default defineConfig/)
    if (exportMatch) {
      const insertPos = exportMatch.index
      content = content.slice(0, insertPos) + pathDetectionCode + '\n' + content.slice(insertPos)
      updated = true
    }
    
    // Generate ULS dev plugin code - Direct CSS compilation (fast, reliable)
    // Uses same logic as vite.config.build.mjs but optimized for dev mode
    const ulsDevPluginCode = `
// ULS Dev Plugin - Tailwind-like auto-rebuild during development
// Directly compiles CSS (no spawn) for instant rebuilds when classes are added
function ulsDevPlugin() {
  // Load ULS config
  let ulsConfig = {}
  try {
    const configPath = resolve(__dirname, 'uls.config.cjs')
    if (existsSync(configPath)) {
      const require = createRequire(import.meta.url)
      ulsConfig = require(configPath)
    }
  } catch (err) {
    // Use defaults
  }
  
  // Resolve paths
  const lessEntry = resolve(ulsPackagePath, 'src/styles/uls-master.less')
  const outDir = resolve(__dirname, 'dist/css')
  const outFile = resolve(__dirname, 'dist/css/uls.css')
  
  // CSS compilation function (same as build plugin, but faster for dev)
  const compileCSS = async () => {
    if (!existsSync(lessEntry)) {
      console.warn('⚠️  ULS LESS entry not found:', lessEntry)
      return
    }
    
    try {
      const less = await import('less')
      const src = readFileSync(lessEntry, 'utf8')
      const entryDir = resolve(lessEntry, '..')
      const nodeModulesPath = resolve(__dirname, 'node_modules')
      
      // Compile LESS
      const cssResult = await less.default.render(src, {
        filename: lessEntry,
        paths: [
          entryDir,
          resolve(ulsPackagePath, 'styles'),
          nodeModulesPath,
          resolve(process.cwd(), 'node_modules'),
          ${uiPackageInfo && uiPackageInfo.useUiPackage ? "resolve(uiPackagePath, 'node_modules')," : ''}
        ],
      })
      
      if (!cssResult || !cssResult.css) {
        console.warn('⚠️  LESS compilation failed: No CSS output')
        return
      }
      
      let css = cssResult.css
      
      // Purge unused CSS (only if purge is enabled in config)
      if (ulsConfig.purge) {
        try {
          const postcss = await import('postcss')
          const purgecssModule = await import('@fullhuman/postcss-purgecss')
          const purgecss = purgecssModule.purgeCSSPlugin || purgecssModule.default?.purgeCSSPlugin || purgecssModule.default
          
          if (purgecss && typeof purgecss === 'function') {
            const purgeConfigPath = resolve(ulsPackagePath, 'src/scripts/purgecss-config.mjs')
            if (existsSync(purgeConfigPath)) {
              const purgeConfigModule = await import(purgeConfigPath)
              const getPurgeCSSConfig = purgeConfigModule.getPurgeCSSConfig
              
              if (getPurgeCSSConfig) {
                const purgeConfig = await getPurgeCSSConfig({ scanJsFiles: false })
                const purgeResult = await postcss.default([
                  purgecss(purgeConfig)
                ]).process(css, { from: undefined })
                
                css = purgeResult.css
              }
            }
          }
        } catch (err) {
          // Continue without purging if it fails
        }
      }
      
      // Ensure output directory exists
      if (!existsSync(outDir)) {
        mkdirSync(outDir, { recursive: true })
      }
      
      // Write CSS file
      writeFileSync(outFile, css, 'utf8')
    } catch (err) {
      console.warn('⚠️  CSS compilation failed:', err.message)
    }
  }
  
  return {
    name: 'uls-dev',
    async buildStart() {
      // Initial CSS build on dev server start
      await compileCSS()
    },
    async handleHotUpdate({ file, server }) {
      // Watch for content file changes and rebuild CSS instantly
      const isContentFile = 
        file.endsWith('.html') ||
        file.endsWith('.jsx') ||
        file.endsWith('.js') ||
        file.endsWith('.tsx') ||
        file.endsWith('.ts') ||
        file.endsWith('.hbs')
      
      if (isContentFile) {
        console.log('📝 Content file changed: ' + file)
        console.log('🔄 Rebuilding ULS CSS with updated classes...')
        
        // Rebuild CSS asynchronously (don't block HMR)
        compileCSS().then(() => {
          console.log('✨ ULS CSS updated automatically!')
          // Trigger CSS HMR update
          const cssModule = server.moduleGraph.getModuleById(resolve(__dirname, 'dist/css/uls.css'))
          if (cssModule) {
            server.moduleGraph.invalidateModule(cssModule)
            server.ws.send({
              type: 'update',
              updates: [{
                type: 'css-update',
                path: '/dist/css/uls.css',
                acceptedPath: '/dist/css/uls.css',
                timestamp: Date.now()
              }]
            })
          }
        }).catch((err) => {
          console.warn('⚠️  CSS rebuild failed:', err.message)
        })
      }
      
      // Don't prevent HMR for content files - let React plugin handle it
      return undefined
    },
    // Watch content files for changes
    async configureServer(server) {
      try {
        const { glob } = await import('glob')
        
        // Always watch src/ directory for React/Vue projects (even if sourceDirs not configured)
        const srcDir = resolve(process.cwd(), 'src')
        if (existsSync(srcDir)) {
          try {
            const srcFiles = glob.sync('src/**/*.{js,jsx,ts,tsx,hbs}', {
              cwd: process.cwd(),
              ignore: ['node_modules/**', 'dist/**'],
              absolute: false
            })
            srcFiles.forEach(file => {
              const fullPath = resolve(process.cwd(), file)
              if (existsSync(fullPath)) {
                server.watcher.add(fullPath)
              }
            })
            console.log('👀 Watching src/ directory for CSS class changes')
          } catch (err) {
            // Continue
          }
        }
        
        // Watch HTML files from config
        if (ulsConfig.purge && ulsConfig.purge.htmlFiles) {
          const htmlFilesToWatch = ulsConfig.purge.htmlFiles || ['index.html']
          
          for (const pattern of htmlFilesToWatch) {
            try {
              const files = glob.sync(pattern, {
                cwd: process.cwd(),
                ignore: ['node_modules/**', 'dist/**'],
                absolute: false
              })
              files.forEach(file => {
                const fullPath = resolve(process.cwd(), file)
                if (existsSync(fullPath)) {
                  server.watcher.add(fullPath)
                }
              })
            } catch (err) {
              // Pattern might not match
            }
          }
        }
        
        // Watch additional source directories if configured
        if (ulsConfig.purge && ulsConfig.purge.sourceDirs && ulsConfig.purge.sourceDirs.length > 0) {
          for (const dir of ulsConfig.purge.sourceDirs) {
            try {
              const files = glob.sync(\`\${dir}/**/*.{js,jsx,ts,tsx,hbs}\`, {
                cwd: process.cwd(),
                ignore: ['node_modules/**', 'dist/**'],
                absolute: false
              })
              files.forEach(file => {
                const fullPath = resolve(process.cwd(), file)
                if (existsSync(fullPath)) {
                  server.watcher.add(fullPath)
                }
              })
            } catch (err) {
              // Continue
            }
          }
        }
      } catch (err) {
        // glob might not be available
      }
    }
  }
}
`
    
    // Add plugin code before export
    const exportMatch2 = content.match(/export default defineConfig/)
    if (exportMatch2) {
      const insertPos = exportMatch2.index
      content = content.slice(0, insertPos) + ulsDevPluginCode + '\n' + content.slice(insertPos)
      updated = true
    }
    
    // Add plugin to plugins array
    const pluginsMatch = content.match(/plugins:\s*\[([^\]]*)\]/)
    if (pluginsMatch) {
      const pluginsContent = pluginsMatch[1]
      if (!pluginsContent.includes('ulsDevPlugin')) {
        const newPlugins = pluginsContent.trim() 
          ? `${pluginsContent.trim()},\n    ulsDevPlugin()`
          : 'ulsDevPlugin()'
        content = content.replace(pluginsMatch[0], `plugins: [\n    ${newPlugins}\n  ]`)
        updated = true
      }
    } else {
      // No plugins array, add it
      const configMatch = content.match(/export default defineConfig\(({[^}]*)\)/)
      if (configMatch) {
        const configContent = configMatch[1]
        if (!configContent.includes('plugins')) {
          content = content.replace(
            configMatch[0],
            `export default defineConfig({\n  plugins: [ulsDevPlugin()],\n  ${configContent}\n})`
          )
          updated = true
        }
      }
    }
  }
  
  if (updated) {
    writeFileSync(configPath, content, 'utf8')
    console.log('✅ Updated ' + path.basename(configPath) + ' with ULS dev plugin')
    
    // Show migration message if needed
    if (migrationMessage) {
      console.log(migrationMessage)
    }
    
    return true
  } else {
    console.log('ℹ️  ' + path.basename(configPath) + ' already has ULS dev plugin')
    
    // Show migration message even if plugin already exists
    if (migrationMessage) {
      console.log(migrationMessage)
    }
    
    return false
  }
}

/**
 * Main function
 */
function main() {
  console.log('🔄 Updating ULS configuration files...\n')
  
  // Find UI package
  const uiPackageInfo = findUiPackage()
  if (uiPackageInfo) {
    if (uiPackageInfo.useUiPackage) {
      const uiPackageName = path.basename(uiPackageInfo.uiPackagePath)
      console.log(`📦 Running in application repository - found UI package: ${uiPackageName}`)
      console.log(`📦 Found ULS at: ${uiPackageInfo.ulsPath}`)
    } else {
      console.log(`📦 Running in UI repository - using ULS directly at: ${uiPackageInfo.ulsPath}`)
    }
  } else {
    // Try to find ULS directly
    const ulsPath = findULSDirect()
    if (ulsPath) {
      console.log(`📦 Found ULS directly at: ${ulsPath}`)
    } else {
      console.error('❌ Neither bs-ui nor uls-v2 found in node_modules')
      console.error('   Make sure bs-ui is linked or uls-v2 is installed')
      process.exit(1)
    }
  }
  
  console.log('')
  
  // Step 1: Ensure package.json has required scripts
  const packageJsonUpdated = ensurePackageJsonScripts(uiPackageInfo)
  
  // Step 2: Update config files
  const viteUpdated = updateViteConfig(uiPackageInfo, findULSDirect())
  const viteDevUpdated = updateViteDevConfig(uiPackageInfo, findULSDirect())
  const configUpdated = updateUlsConfig()
  
  if (packageJsonUpdated || viteUpdated || viteDevUpdated || configUpdated) {
    console.log('\n✅ Configuration updated successfully!')
    if (packageJsonUpdated) {
      console.log('   • package.json scripts updated')
    }
    if (viteUpdated) {
      console.log('   • vite.config.build.mjs updated')
    }
    if (viteDevUpdated) {
      console.log('   • vite.config.js updated with ULS dev plugin')
    }
    if (configUpdated) {
      console.log('   • uls.config.cjs updated')
    }
    console.log('   Run: npm run dev (CSS will auto-rebuild on file changes!)')
  } else {
    console.log('\n✅ Configuration files are up to date!')
  }
}

main()

